94	// Stubs sit contiguously just past the boot image, well inside the proc table.
95	const _: () = assert!(STUB_A_PROC_NR.get() as usize == NR_BOOT_PROCS);
96	const _: () = assert!(STUB_D_PROC_NR.get() as usize == NR_BOOT_PROCS + NR_STUB_PROCS - 1);
