// SPDX-License-Identifier: BSD-3-Clause
// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
// minix.rs Microkernel
#![cfg_attr(target_os = "none", no_std)]
#![cfg_attr(target_os = "none", no_main)]

// The kernel crate is only meaningful on bare-metal targets (`target_os =
// "none"`). When `cargo check --workspace` runs against the host target
// (macos / linux), we collapse to a no-op `main` so the workspace stays
// checkable; the ELF-only `link_section` attributes, the `_start` entry
// path, and the panic handler all rely on the bare-metal target.

#[cfg(target_os = "none")]
mod arch;
#[cfg(target_os = "none")]
mod boot_image;
#[cfg(target_os = "none")]
mod clock;
#[cfg(target_os = "none")]
mod ipc;
#[cfg(target_os = "none")]
mod mm;
#[cfg(target_os = "none")]
mod panic;
#[cfg(target_os = "none")]
mod proc;
#[cfg(target_os = "none")]
mod system;
#[cfg(target_os = "none")]
mod uart;

#[cfg(target_os = "none")]
use core::fmt::Write;

/// Scheduler tick rate (Hz). 100 Hz → 10 ms ticks, matching the classic
/// MINIX 3 cadence. Combined with the per-stub `quantum_ms = 5`, each task
/// gets ~50 ms of CPU before preemption.
#[cfg(target_os = "none")]
const TICK_HZ: u64 = 100;

#[cfg(target_os = "none")]
#[unsafe(no_mangle)]
extern "C" fn kmain() -> ! {
    // Resolve the UART MMIO virtual address before any output. Limine maps
    // PL011 into the HHDM (under base revision 2, the [0, 4 GiB) blanket
    // map covers device memory); we fall back to the physical address if
    // the bootloader didn't populate the response.
    let hhdm = arch::limine_hhdm_offset().unwrap_or(0);
    arch::set_uart_base(hhdm as usize + arch::PL011_PHYS_BASE);

    arch::init();

    let mut con = uart::Uart::new();
    let _ = writeln!(con, "minix.rs booting on aarch64");

    if arch::limine_base_revision_supported() {
        let _ = writeln!(con, "HHDM offset: {hhdm:#018x}");
    } else {
        let _ = writeln!(con, "Limine base revision unsupported (loader is too old)");
    }

    proc::init();
    let _ = writeln!(con);
    let _ = proc::dump_tables(&mut con);

    // Slice 3.1a: capture Limine's HHDM offset and populate the physical
    // frame allocator from the memmap. Both are prerequisites for the
    // address-space API (`arch::aarch64::addrspace::AddrSpace`) — which
    // slice 3.1b's `userland_bootstrap` now drives in earnest, one
    // AddrSpace per EL0 stub.
    // SAFETY: single-threaded boot; this is the only writer of HHDM_OFFSET
    // and the only initializer of the allocator.
    unsafe {
        mm::set_hhdm_offset(hhdm);
        mm::init_from_limine_memmap();
    }

    // Slice 2.4: bring up the interrupt controller and timer, populate two
    // EL0 stub tasks, enqueue them, and hand control to the scheduler.
    // SAFETY: single-threaded boot; DAIF still masked from Limine handoff.
    unsafe { arch::aarch64::gic::init() };
    // SAFETY: same; gic is configured first so the timer's PPI 27 is routable.
    unsafe {
        arch::aarch64::gic::enable_ppi(arch::aarch64::timer::INTID_VIRT_TIMER, 0x80);
    }
    // SAFETY: same; programs CNTV_TVAL_EL0 + CNTV_CTL_EL0.
    unsafe { arch::aarch64::timer::init(TICK_HZ) };

    let _ = writeln!(
        con,
        "\nentering EL0 stub tasks (preemption demo: A/B interleaved by timer)..."
    );

    // SAFETY: single-threaded boot context; no other reference into the
    // page-table arena, user pages, or stub proc slots exists. Bootstrap
    // populates both stub slots and enqueues them.
    unsafe { arch::userland_bootstrap() };

    // SAFETY: at least one proc is enqueued (we just enqueued two); first
    // eret transitions from EL1 boot context into EL0 user execution.
    unsafe { proc::sched::run() }
}

#[cfg(not(target_os = "none"))]
fn main() {}

// SPDX-License-Identifier: BSD-3-Clause
// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
// IoRange/MemRange fields and several constants are forward declarations for
// slice 2.6 (kernel-call dispatch) — they are written by `proc::init` and read
// once slices 2.5/2.6 wire up IPC and `SYS_*` handlers.
#![allow(dead_code)]

//! Privilege-table entry.
//!
//! Mirrors MINIX 3 `kernel/priv.h`'s `struct priv` with the same simplifications
//! as [`Proc`]: no SMP, no live update, no profiling. The bitmaps are sized to
//! `NR_SYS_PROCS` (for IPC / notify / asyn target maps) and `NR_SYS_CALLS`
//! (for the kernel-call mask).
//!
//! [`Proc`]: super::Proc

use arrayvec::ArrayVec;

use minixrs_kernel_shared::callnr::NR_SYS_CALLS;
use minixrs_kernel_shared::com::NR_SYS_PROCS;
use minixrs_kernel_shared::endpoint::{Endpoint, NONE};
use minixrs_kernel_shared::sys_limits::{NR_IO_RANGE, NR_IRQ, NR_MEM_RANGE};
use minixrs_kernel_shared::{PrivId, ProcNr};

/// Number of `u32` chunks needed to cover `NR_SYS_PROCS` bits.
pub const IPC_MAP_CHUNKS: usize = NR_SYS_PROCS / 32;
/// Number of `u32` chunks needed to cover `NR_SYS_CALLS` bits.
pub const K_CALL_MASK_CHUNKS: usize = NR_SYS_CALLS / 32;

const _: () = assert!(NR_SYS_PROCS % 32 == 0);

/// I/O port range a privileged process may access.
#[derive(Copy, Clone, Debug, Default)]
pub struct IoRange {
    pub base: u64,
    pub count: u64,
}

/// Physical memory range a privileged process may map.
#[derive(Copy, Clone, Debug, Default)]
pub struct MemRange {
    pub base: u64,
    pub count: u64,
}

/// One slot in the kernel's privilege table.
///
/// Each system (privileged) process owns exactly one `Priv`; user processes
/// share a single user-class slot (`USER_PRIV_ID`).
#[repr(C)]
pub struct Priv {
    /// Slot index into the privilege table.
    pub id: PrivId,
    /// Process this slot belongs to, if any.
    pub proc_nr: Option<ProcNr>,
    /// Privilege flags (`PREEMPTIBLE`, `SYS_PROC`, …).
    pub flags: u16,
    /// Trap mask — bit `i` allows IPC primitive `i`.
    pub trap_mask: u16,

    // ----- IPC target / pending bitmaps ------------------------------------
    /// Bitmap of privileged slots this process may send to.
    pub ipc_to: [u32; IPC_MAP_CHUNKS],
    /// Bitmap of allowed kernel calls.
    pub k_call_mask: [u32; K_CALL_MASK_CHUNKS],
    /// Bitmap of pending notifications.
    pub notify_pending: [u32; IPC_MAP_CHUNKS],
    /// Bitmap of pending async messages.
    pub asyn_pending: [u32; IPC_MAP_CHUNKS],

    /// Signal manager endpoint (delivers signals raised against us).
    pub sig_mgr: Endpoint,

    // ----- Resource ownership ---------------------------------------------
    pub io_ranges: ArrayVec<IoRange, NR_IO_RANGE>,
    pub mem_ranges: ArrayVec<MemRange, NR_MEM_RANGE>,
    pub irqs: ArrayVec<u32, NR_IRQ>,

    /// Address of the grant table within the owner's address space (set by
    /// `SYS_SETGRANT`); slice 2.6 starts honoring this.
    pub grant_table: u64,
    /// Number of grant-table entries.
    pub grant_entries: u32,
}

impl Priv {
    /// Empty-slot initializer used to fill the static privilege table at boot.
    pub const EMPTY: Self = Self {
        id: PrivId::new(0),
        proc_nr: None,
        flags: 0,
        trap_mask: 0,
        ipc_to: [0; IPC_MAP_CHUNKS],
        k_call_mask: [0; K_CALL_MASK_CHUNKS],
        notify_pending: [0; IPC_MAP_CHUNKS],
        asyn_pending: [0; IPC_MAP_CHUNKS],
        sig_mgr: NONE,
        io_ranges: ArrayVec::new_const(),
        mem_ranges: ArrayVec::new_const(),
        irqs: ArrayVec::new_const(),
        grant_table: 0,
        grant_entries: 0,
    };
}

